<?php
namespace App\Http\Controllers;use App\Models\{Employee,EmployeeResignation};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class ResignationController extends Controller{public function __construct(){$this->middleware('auth');}
 public function index(Request $r){$q=EmployeeResignation::with('employee')->latest('resignation_date');$q->when($r->search,fn($q,$v)=>$q->whereHas('employee',fn($e)=>$e->where('name','like',"%$v%")->orWhere('email','like',"%$v%")))->when($r->employee_id,fn($q,$v)=>$q->where('employee_id',$v))->when($r->from,fn($q,$v)=>$q->whereDate('resignation_date','>=',$v))->when($r->to,fn($q,$v)=>$q->whereDate('resignation_date','<=',$v))->when($r->status&&$r->status!=='All',fn($q)=>$q->where('status',$r->status));$counts=['All'=>EmployeeResignation::count(),'Pending'=>EmployeeResignation::whereStatus('Pending')->count(),'Approved'=>EmployeeResignation::whereStatus('Approved')->count(),'Rejected'=>EmployeeResignation::whereStatus('Rejected')->count(),'Completed'=>EmployeeResignation::whereStatus('Completed')->count()];return view('resignations.index',['resignations'=>$q->paginate(10)->withQueryString(),'employees'=>Employee::orderBy('name')->get(),'counts'=>$counts]);}
 public function store(Request $r){$this->save($r,new EmployeeResignation);return back()->with('success','Resignation created successfully.');}public function update(Request $r,EmployeeResignation $resignation){$this->save($r,$resignation);return back()->with('success','Resignation updated successfully.');}
 public function status(Request $r,EmployeeResignation $resignation){$d=$r->validate(['status'=>'required|in:Pending,Approved,Rejected,Completed','exit_interview_conducted'=>'nullable|boolean','exit_interview_date'=>'nullable|date','exit_feedback'=>'nullable|string|max:2000']);$d['exit_interview_conducted']=$r->boolean('exit_interview_conducted');$resignation->update($d);if($d['status']==='Completed')$resignation->employee()->update(['employment_status'=>'Inactive','login_status'=>0]);return back()->with('success','Resignation status updated.');}
 public function document(EmployeeResignation $resignation){abort_unless($resignation->document_path&&Storage::disk('public')->exists($resignation->document_path),404);return Storage::disk('public')->response($resignation->document_path);}public function destroy(EmployeeResignation $resignation){if($resignation->document_path)Storage::disk('public')->delete($resignation->document_path);$resignation->delete();return back()->with('success','Resignation deleted.');}
 private function save(Request $r,EmployeeResignation $x):void{$d=$r->validate(['employee_id'=>'required|exists:employees,id','resignation_date'=>'required|date','last_working_day'=>'nullable|date|after_or_equal:resignation_date','notice_period'=>'nullable|string|max:50','reason'=>'required|string|max:191','description'=>'nullable|string|max:3000','document'=>'nullable|file|mimes:pdf,jpg,jpeg,png,doc,docx|max:5120']);unset($d['document']);if(empty($d['last_working_day'])){$d['last_working_day']=\Carbon\Carbon::parse($d['resignation_date'])->addDays(14)->toDateString();$d['notice_period']='2 weeks';}if($r->hasFile('document')){if($x->document_path)Storage::disk('public')->delete($x->document_path);$d['document_path']=$r->file('document')->store('resignations','public');}$x->fill($d)->save();}}
